              </div>
              <div className="config-field">
                <label>Stop Time (s)</label>
                <input
                  type="number"
                  step="any"
                  min="0"
                  value={templateConfig.stop_time}
                  onChange={e => handleConfigChange('stop_time', e.target.value)}
